/* ============================================================
   SHELL & DEBT — dev/bundle.js
   ONE FILE.

   The game is twenty script tags and a stylesheet, which is the
   right way to keep it while it is being written and the wrong way
   to hand it to somebody on a phone: twenty round trips through
   whatever CDN is in front of it, any one of which can 404.

   This inlines the lot — same order, same code, nothing minified —
   into dist/shell-and-debt.html, which is a single self-contained
   page you can open from a file, a chat window or a static host.

     node dev/bundle.js
   ============================================================ */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');

let out = html;
let css = 0, js = 0;

/* the stylesheet */
out = out.replace(/[ \t]*<link rel="stylesheet" href="([^"]+)">/g, (m, href) => {
  const file = path.join(root, href);
  css++;
  return '<style>\n' + fs.readFileSync(file, 'utf8').trimEnd() + '\n</style>';
});

/* every script, in the order the page loads them */
out = out.replace(/[ \t]*<script src="([^"]+)"><\/script>/g, (m, src) => {
  const file = path.join(root, src);
  js++;
  const code = fs.readFileSync(file, 'utf8').trimEnd();
  return '<script>\n/* ==== ' + src + ' ==== */\n' + code + '\n</script>';
});

if (/<script src=|<link rel="stylesheet"/.test(out)) {
  console.error('bundle: something did not get inlined');
  process.exit(1);
}

/* a note at the top so whoever opens the file knows what it is */
const stamp = '<!--\n  SHELL & DEBT — one-file build.\n' +
  '  Generated by dev/bundle.js from index.html; do not edit this file.\n' +
  '  Every sprite, room, letter and cutscene is still drawn by the code below\n' +
  '  at boot: there are no image assets and nothing is fetched.\n-->\n';
out = out.replace('<!DOCTYPE html>', '<!DOCTYPE html>\n' + stamp);

const dist = path.join(root, 'dist');
if (!fs.existsSync(dist)) fs.mkdirSync(dist);
const dest = path.join(dist, 'shell-and-debt.html');
fs.writeFileSync(dest, out);

const kb = (Buffer.byteLength(out) / 1024).toFixed(0);
console.log('bundled ' + js + ' scripts + ' + css + ' stylesheet -> dist/shell-and-debt.html (' + kb + ' KB)');
